#!/usr/bin/env python3
"""Cat's nmap 1.x — single-file app; nmap is pre-baked after the code as comments."""

from __future__ import annotations

import base64
import hashlib
import io
import os
import shlex
import shutil
import subprocess
import sys
import tarfile
import tempfile
import threading
import tkinter as tk
from pathlib import Path
from tkinter import messagebox, scrolledtext, ttk

BG = "#0a1a3a"
BG_PANEL = "#0f2248"
FG = "#5eb0ff"
FG_DIM = "#3a7ab8"
BTN_BG = "#000000"
BTN_FG = "#5eb0ff"
BTN_ACTIVE = "#1a1a1a"
ENTRY_BG = "#061028"
ENTRY_FG = "#5eb0ff"
ACCENT = "#1e90ff"

WINDOW_W = 1920
WINDOW_H = 1080
TITLE = "Cat's nmap 1.x"

PAYLOAD_START = "# ===NMAP_TGZ_B64_START==="
PAYLOAD_END = "# ===NMAP_TGZ_B64_END==="
PAYLOAD_LINE = "#NMAP:"

_CACHE_LOCK = threading.Lock()
_RESOLVED: tuple[str | None, dict[str, str]] | None = None


def is_root() -> bool:
    try:
        return os.geteuid() == 0
    except AttributeError:
        return False


def _app_file() -> Path:
    return Path(__file__).resolve()


def _read_embedded_b64() -> str:
    """Load pre-baked nmap from trailing comment lines (keeps import fast)."""
    parts: list[str] = []
    in_payload = False
    with _app_file().open("r", encoding="utf-8", errors="strict") as fh:
        for line in fh:
            s = line.rstrip("\n")
            if s == PAYLOAD_START:
                in_payload = True
                continue
            if s == PAYLOAD_END:
                break
            if in_payload and s.startswith(PAYLOAD_LINE):
                parts.append(s[len(PAYLOAD_LINE) :])
    return "".join(parts)


def _cache_root(digest: str) -> Path:
    return Path(tempfile.gettempdir()) / f"catsnmap1.x-{digest}"


def materialize_nmap() -> tuple[str | None, dict[str, str]]:
    """Decode embedded nmap once into a verified temp cache."""
    global _RESOLVED
    if _RESOLVED is not None:
        return _RESOLVED

    with _CACHE_LOCK:
        if _RESOLVED is not None:
            return _RESOLVED

        env: dict[str, str] = {}
        try:
            b64 = _read_embedded_b64()
        except OSError:
            _RESOLVED = (None, env)
            return _RESOLVED

        if not b64:
            _RESOLVED = (None, env)
            return _RESOLVED

        digest = hashlib.sha256(b64.encode("ascii")).hexdigest()[:16]
        cache = _cache_root(digest)
        nmap_bin = cache / "bin" / "nmap"
        nmap_dir = cache / "share" / "nmap"
        marker = cache / ".ok"

        if not (nmap_bin.is_file() and marker.is_file() and marker.read_text(encoding="utf-8").strip() == digest):
            staging = Path(tempfile.mkdtemp(prefix="catsnmap-extract-"))
            try:
                raw = base64.b64decode(b64, validate=False)
                extract_kwargs = {"path": staging}
                # Python 3.12+ data filter avoids unsafe tar members
                if sys.version_info >= (3, 12):
                    extract_kwargs["filter"] = "data"
                with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
                    tar.extractall(**extract_kwargs)
                extracted = staging / "nmap"
                if not extracted.is_dir():
                    raise RuntimeError("embedded archive missing nmap/ root")
                if cache.exists():
                    shutil.rmtree(cache, ignore_errors=True)
                shutil.move(str(extracted), str(cache))
                nmap_bin.chmod(0o755)
                # Re-sign after move (macOS may invalidate ad-hoc sig on copy)
                subprocess.run(
                    ["codesign", "-s", "-", "--force", "--deep", str(nmap_bin)],
                    check=False,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                for dylib in (cache / "lib").glob("*.dylib"):
                    subprocess.run(
                        ["codesign", "-s", "-", "--force", str(dylib)],
                        check=False,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.DEVNULL,
                    )
                test_env = os.environ.copy()
                if nmap_dir.is_dir():
                    test_env["NMAPDIR"] = str(nmap_dir)
                probe = subprocess.run(
                    [str(nmap_bin), "--version"],
                    capture_output=True,
                    text=True,
                    env=test_env,
                    timeout=20,
                    check=False,
                )
                if probe.returncode != 0:
                    raise RuntimeError(
                        f"embedded nmap failed:\n{probe.stderr or probe.stdout}"
                    )
                marker.write_text(digest + "\n", encoding="utf-8")
            finally:
                shutil.rmtree(staging, ignore_errors=True)

        if not nmap_bin.is_file():
            _RESOLVED = (None, env)
            return _RESOLVED

        if nmap_dir.is_dir():
            env["NMAPDIR"] = str(nmap_dir)
        _RESOLVED = (str(nmap_bin), env)
        return _RESOLVED


def resolve_nmap() -> tuple[str | None, dict[str, str]]:
    return materialize_nmap()


class CatsNmapApp(tk.Tk):
    def __init__(self) -> None:
        super().__init__()
        self.title(TITLE)
        self.configure(bg=BG)
        self._center_window(WINDOW_W, WINDOW_H)
        self.resizable(True, True)
        self.minsize(960, 540)

        self._scan_proc: subprocess.Popen[str] | None = None
        self._scanning = False
        self._stop_requested = False
        self._ready_status = "Ready"
        self.nmap_path: str | None = None
        self.nmap_env: dict[str, str] = {}

        self._build_ui()
        self._wire_option_guards()
        self.after(50, self._boot_nmap)

    def _center_window(self, width: int, height: int) -> None:
        self.update_idletasks()
        sw = self.winfo_screenwidth()
        sh = self.winfo_screenheight()
        width = min(width, max(800, sw))
        height = min(height, max(500, sh))
        x = max(0, (sw - width) // 2)
        y = max(0, (sh - height) // 2)
        self.geometry(f"{width}x{height}+{x}+{y}")

    def _boot_nmap(self) -> None:
        self.status_var.set("Unpacking pre-baked nmap…")
        self.scan_btn.configure(state=tk.DISABLED)

        def work() -> None:
            err: str | None = None
            path: str | None = None
            env: dict[str, str] = {}
            try:
                path, env = resolve_nmap()
            except Exception as exc:
                err = str(exc)
            self.after(0, self._on_nmap_ready, path, env, err)

        threading.Thread(target=work, daemon=True).start()

    def _on_nmap_ready(
        self,
        path: str | None,
        env: dict[str, str],
        err: str | None,
    ) -> None:
        self.nmap_path = path
        self.nmap_env = env
        if err or not path:
            self._ready_status = "nmap missing"
            self.status_var.set(self._ready_status)
            messagebox.showerror(
                TITLE,
                "Could not load pre-baked nmap from this file.\n"
                + (err or "Payload missing or corrupt."),
            )
            return
        priv = "root" if is_root() else "user"
        self._ready_status = f"Ready · pre-baked nmap · {priv}"
        self.status_var.set(self._ready_status)
        self.scan_btn.configure(state=tk.NORMAL)

    def _build_ui(self) -> None:
        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure("Blue.TFrame", background=BG)
        style.configure("Panel.TFrame", background=BG_PANEL)
        style.configure(
            "Blue.TLabel", background=BG, foreground=FG, font=("Helvetica", 12)
        )
        style.configure(
            "Title.TLabel",
            background=BG,
            foreground=ACCENT,
            font=("Helvetica", 28, "bold"),
        )
        style.configure(
            "Dim.TLabel", background=BG, foreground=FG_DIM, font=("Helvetica", 10)
        )
        style.configure(
            "Panel.TLabelframe",
            background=BG_PANEL,
            foreground=FG,
            bordercolor=ACCENT,
            font=("Helvetica", 11, "bold"),
        )
        style.configure(
            "Panel.TLabelframe.Label",
            background=BG_PANEL,
            foreground=ACCENT,
            font=("Helvetica", 11, "bold"),
        )
        style.configure(
            "Blue.TCheckbutton",
            background=BG_PANEL,
            foreground=FG,
            font=("Helvetica", 11),
        )
        style.map(
            "Blue.TCheckbutton",
            background=[("active", BG_PANEL)],
            foreground=[("active", FG)],
        )

        root = ttk.Frame(self, style="Blue.TFrame", padding=24)
        root.pack(fill=tk.BOTH, expand=True)

        header = ttk.Frame(root, style="Blue.TFrame")
        header.pack(fill=tk.X, pady=(0, 16))
        ttk.Label(header, text=TITLE, style="Title.TLabel").pack(side=tk.LEFT)
        ttk.Label(
            header, text="authorized network discovery only", style="Dim.TLabel"
        ).pack(side=tk.RIGHT, pady=12)

        target_row = ttk.Frame(root, style="Blue.TFrame")
        target_row.pack(fill=tk.X, pady=(0, 12))
        ttk.Label(target_row, text="Target", style="Blue.TLabel").pack(
            side=tk.LEFT, padx=(0, 12)
        )
        self.target_var = tk.StringVar(value="127.0.0.1")
        self.target_entry = tk.Entry(
            target_row,
            textvariable=self.target_var,
            bg=ENTRY_BG,
            fg=ENTRY_FG,
            insertbackground=FG,
            relief=tk.FLAT,
            font=("Menlo", 14),
            highlightthickness=1,
            highlightbackground=ACCENT,
            highlightcolor=ACCENT,
        )
        self.target_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, ipady=8)
        self.target_entry.bind("<Return>", lambda _e: self._on_scan())

        opts = ttk.LabelFrame(
            root, text=" Scan options ", style="Panel.TLabelframe", padding=16
        )
        opts.pack(fill=tk.X, pady=(0, 12))
        for c in range(3):
            opts.columnconfigure(c, weight=1)

        self.opt_connect = tk.BooleanVar(value=not is_root())
        self.opt_syn = tk.BooleanVar(value=is_root())
        self.opt_service = tk.BooleanVar(value=False)
        self.opt_os = tk.BooleanVar(value=False)
        self.opt_ping = tk.BooleanVar(value=False)
        self.opt_udp = tk.BooleanVar(value=False)
        self.opt_verbose = tk.BooleanVar(value=True)

        checks = [
            (self.opt_connect, "Connect scan (-sT)"),
            (self.opt_syn, "SYN scan (-sS, needs root)"),
            (self.opt_service, "Service/version (-sV)"),
            (self.opt_os, "OS detection (-O, needs root)"),
            (self.opt_ping, "Ping only (-sn)"),
            (self.opt_udp, "UDP scan (-sU, needs root)"),
            (self.opt_verbose, "Verbose (-v)"),
        ]
        for i, (var, label) in enumerate(checks):
            ttk.Checkbutton(
                opts, text=label, variable=var, style="Blue.TCheckbutton"
            ).grid(row=i // 3, column=i % 3, sticky=tk.W, padx=12, pady=6)

        ports_row = ttk.Frame(opts, style="Panel.TFrame")
        ports_row.grid(row=3, column=0, columnspan=3, sticky=tk.EW, pady=(8, 0))
        tk.Label(
            ports_row, text="Ports", bg=BG_PANEL, fg=FG, font=("Helvetica", 12)
        ).pack(side=tk.LEFT, padx=(0, 12))
        self.ports_var = tk.StringVar(value="")
        self.ports_entry = tk.Entry(
            ports_row,
            textvariable=self.ports_var,
            bg=ENTRY_BG,
            fg=ENTRY_FG,
            insertbackground=FG,
            relief=tk.FLAT,
            font=("Menlo", 12),
            highlightthickness=1,
            highlightbackground=ACCENT,
            highlightcolor=ACCENT,
            width=40,
        )
        self.ports_entry.pack(side=tk.LEFT, ipady=4)
        tk.Label(
            ports_row,
            text="e.g. 22,80,443 or 1-1024  (empty = nmap default)",
            bg=BG_PANEL,
            fg=FG_DIM,
            font=("Helvetica", 10),
        ).pack(side=tk.LEFT, padx=12)

        extra_row = ttk.Frame(opts, style="Panel.TFrame")
        extra_row.grid(row=4, column=0, columnspan=3, sticky=tk.EW, pady=(8, 0))
        tk.Label(
            extra_row, text="Extra args", bg=BG_PANEL, fg=FG, font=("Helvetica", 12)
        ).pack(side=tk.LEFT, padx=(0, 12))
        self.extra_var = tk.StringVar(value="")
        self.extra_entry = tk.Entry(
            extra_row,
            textvariable=self.extra_var,
            bg=ENTRY_BG,
            fg=ENTRY_FG,
            insertbackground=FG,
            relief=tk.FLAT,
            font=("Menlo", 12),
            highlightthickness=1,
            highlightbackground=ACCENT,
            highlightcolor=ACCENT,
        )
        self.extra_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, ipady=4)

        btn_row = ttk.Frame(root, style="Blue.TFrame")
        btn_row.pack(fill=tk.X, pady=(0, 12))

        self.scan_btn = self._make_button(btn_row, "Scan", self._on_scan)
        self.scan_btn.pack(side=tk.LEFT, padx=(0, 8))
        self.scan_btn.configure(state=tk.DISABLED)
        self.stop_btn = self._make_button(btn_row, "Stop", self._on_stop)
        self.stop_btn.pack(side=tk.LEFT, padx=(0, 8))
        self.stop_btn.configure(state=tk.DISABLED)
        self.clear_btn = self._make_button(btn_row, "Clear", self._on_clear)
        self.clear_btn.pack(side=tk.LEFT, padx=(0, 8))

        self.status_var = tk.StringVar(value="Starting…")
        tk.Label(
            btn_row,
            textvariable=self.status_var,
            bg=BG,
            fg=FG_DIM,
            font=("Helvetica", 11),
        ).pack(side=tk.RIGHT)

        out_frame = ttk.LabelFrame(
            root, text=" Output ", style="Panel.TLabelframe", padding=8
        )
        out_frame.pack(fill=tk.BOTH, expand=True)
        self.output = scrolledtext.ScrolledText(
            out_frame,
            bg=ENTRY_BG,
            fg=FG,
            insertbackground=FG,
            relief=tk.FLAT,
            font=("Menlo", 12),
            wrap=tk.WORD,
            highlightthickness=1,
            highlightbackground=ACCENT,
            highlightcolor=ACCENT,
        )
        self.output.pack(fill=tk.BOTH, expand=True)
        self.output.configure(state=tk.DISABLED)

        self.protocol("WM_DELETE_WINDOW", self._on_close)

    def _wire_option_guards(self) -> None:
        def on_ping(*_a) -> None:
            if self.opt_ping.get():
                self.opt_connect.set(False)
                self.opt_syn.set(False)
                self.opt_udp.set(False)
                self.opt_service.set(False)
                self.opt_os.set(False)
                self.ports_entry.configure(state=tk.DISABLED)
            else:
                self.ports_entry.configure(state=tk.NORMAL)
                if not self.opt_connect.get() and not self.opt_syn.get():
                    self.opt_connect.set(True)

        def on_syn(*_a) -> None:
            if self.opt_syn.get():
                self.opt_connect.set(False)
                self.opt_ping.set(False)

        def on_connect(*_a) -> None:
            if self.opt_connect.get():
                self.opt_syn.set(False)
                self.opt_ping.set(False)

        self.opt_ping.trace_add("write", on_ping)
        self.opt_syn.trace_add("write", on_syn)
        self.opt_connect.trace_add("write", on_connect)

    def _make_button(self, parent, text: str, command) -> tk.Button:
        return tk.Button(
            parent,
            text=text,
            command=command,
            bg=BTN_BG,
            fg=BTN_FG,
            activebackground=BTN_ACTIVE,
            activeforeground=FG,
            disabledforeground=FG_DIM,
            relief=tk.FLAT,
            font=("Helvetica", 12, "bold"),
            padx=24,
            pady=10,
            cursor="hand2",
            highlightthickness=1,
            highlightbackground=ACCENT,
            highlightcolor=ACCENT,
        )

    def _append_output(self, text: str) -> None:
        if not self.winfo_exists():
            return
        self.output.configure(state=tk.NORMAL)
        self.output.insert(tk.END, text)
        self.output.see(tk.END)
        self.output.configure(state=tk.DISABLED)

    def _set_scanning(self, active: bool) -> None:
        self._scanning = active
        can_scan = bool(self.nmap_path) and not active
        self.scan_btn.configure(state=tk.NORMAL if can_scan else tk.DISABLED)
        self.stop_btn.configure(state=tk.NORMAL if active else tk.DISABLED)
        if active:
            self.status_var.set("Scanning…")
        elif self._stop_requested:
            self.status_var.set("Stopped")
            self._stop_requested = False
        else:
            self.status_var.set(self._ready_status)

    def _build_cmd(self) -> list[str] | None:
        target = self.target_var.get().strip()
        if not target:
            messagebox.showerror(TITLE, "Enter a target host or network.")
            return None
        if not self.nmap_path:
            messagebox.showerror(TITLE, "Pre-baked nmap is not ready yet.")
            return None

        needs_root = (
            (self.opt_syn.get() or self.opt_udp.get() or self.opt_os.get())
            and not self.opt_ping.get()
        )
        if needs_root and not is_root():
            messagebox.showerror(
                TITLE,
                "SYN / UDP / OS detection need root.\n"
                "Use Connect scan (-sT), or run this app with sudo.",
            )
            return None

        cmd = [self.nmap_path]
        if self.opt_ping.get():
            cmd.append("-sn")
        else:
            if self.opt_syn.get():
                cmd.append("-sS")
            elif self.opt_connect.get():
                cmd.append("-sT")
            else:
                cmd.append("-sT")
            if self.opt_udp.get():
                cmd.append("-sU")
            if self.opt_service.get():
                cmd.append("-sV")
            if self.opt_os.get():
                cmd.append("-O")
            ports = self.ports_var.get().strip()
            if ports:
                cmd.extend(["-p", ports])
        if self.opt_verbose.get():
            cmd.append("-v")

        extra = self.extra_var.get().strip()
        if extra:
            try:
                cmd.extend(shlex.split(extra))
            except ValueError as exc:
                messagebox.showerror(TITLE, f"Invalid extra args:\n{exc}")
                return None

        cmd.append(target)
        return cmd

    def _on_scan(self) -> None:
        if self._scanning:
            return
        cmd = self._build_cmd()
        if not cmd:
            return
        self._stop_requested = False
        self._on_clear()
        self._append_output(f"$ nmap {' '.join(cmd[1:])}\n\n")
        self._set_scanning(True)
        threading.Thread(target=self._run_scan, args=(cmd,), daemon=True).start()

    def _run_scan(self, cmd: list[str]) -> None:
        try:
            env = os.environ.copy()
            env.update(self.nmap_env)
            self._scan_proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
                env=env,
            )
            assert self._scan_proc.stdout is not None
            for line in self._scan_proc.stdout:
                self.after(0, self._append_output, line)
            code = self._scan_proc.wait()
            self.after(0, self._append_output, f"\n[exit {code}]\n")
        except FileNotFoundError:
            self.after(
                0,
                lambda: messagebox.showerror(TITLE, "Pre-baked nmap is missing."),
            )
        except Exception as exc:
            self.after(0, self._append_output, f"\nError: {exc}\n")
        finally:
            self._scan_proc = None
            self.after(0, self._set_scanning, False)

    def _on_stop(self) -> None:
        proc = self._scan_proc
        if proc and proc.poll() is None:
            self._stop_requested = True
            proc.terminate()
            try:
                proc.wait(timeout=3)
            except subprocess.TimeoutExpired:
                proc.kill()
            self._append_output("\n[stopped]\n")
            self.status_var.set("Stopped")

    def _on_clear(self) -> None:
        self.output.configure(state=tk.NORMAL)
        self.output.delete("1.0", tk.END)
        self.output.configure(state=tk.DISABLED)

    def _on_close(self) -> None:
        proc = self._scan_proc
        if proc and proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except subprocess.TimeoutExpired:
                proc.kill()
        self.destroy()


def main() -> None:
    app = CatsNmapApp()
    app.mainloop()


if __name__ == "__main__":
    main()

